import{_ as r,c as a,o as e,aj as h}from"./chunks/framework.C2N4vG9O.js";const u=JSON.parse('{"title":"场景教程导览","description":"Torch-RecHub 场景教程概览与示例入口","frontmatter":{"title":"场景教程导览","description":"Torch-RecHub 场景教程概览与示例入口"},"headers":[],"relativePath":"zh/tutorials/intro.md","filePath":"zh/tutorials/intro.md"}'),d={name:"zh/tutorials/intro.md"};function o(l,t,i,n,s,c){return e(),a("div",null,[...t[0]||(t[0]=[h('<h1 id="场景教程导览" tabindex="-1">场景教程导览 <a class="header-anchor" href="#场景教程导览" aria-label="Permalink to “场景教程导览”">​</a></h1><p>想先确认环境能训练模型，可以从<a href="/torch-rechub/zh/guide/quick_start.html">快速开始</a>跑一次 DeepFM。下面三篇教程按任务组织，使用仓库自带的数据。在仓库根目录打开 Notebook 或终端，示例里的相对路径就能找到数据文件。</p><h2 id="教程列表" tabindex="-1">教程列表 <a class="header-anchor" href="#教程列表" aria-label="Permalink to “教程列表”">​</a></h2><ul><li><strong>给候选广告排序</strong>。用 Criteo 的一条曝光记录预测点击概率，再用 AUC 检查模型能否把点击过的广告排在前面。<a href="/torch-rechub/zh/tutorials/ctr.html">排序教程</a></li><li><strong>从电影库找候选</strong>。用 MovieLens 训练 DSSM，分别算出用户向量和电影向量，然后为一个用户取回 10 部电影。<a href="/torch-rechub/zh/tutorials/retrieval.html">召回教程</a></li><li><strong>同时预测点击和购买</strong>。用 Ali-CCP 的两列标签训练 MMOE 或 PLE，分别查看两个任务的 AUC。ESMM 的例子还会用到“点击且购买”这一列。<a href="/torch-rechub/zh/tutorials/pipeline.html">多任务教程</a></li></ul><h2 id="模型使用示例" tabindex="-1">模型使用示例 <a class="header-anchor" href="#模型使用示例" aria-label="Permalink to “模型使用示例”">​</a></h2><p>已经选好模型，可以直接打开对应的教程查看它需要哪些字段。</p><h3 id="排序模型" tabindex="-1">排序模型 <a class="header-anchor" href="#排序模型" aria-label="Permalink to “排序模型”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td>DeepFM</td><td>FM + Deep 联合模型</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/deepfm.html">DeepFM 教程</a></td></tr><tr><td>Wide&amp;Deep</td><td>线性层和多层网络一起打分</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/widedeep.html">Wide&amp;Deep 教程</a></td></tr><tr><td>DCN / DCNv2</td><td>显式特征交叉网络</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/dcn.html">DCN 教程</a></td></tr><tr><td>DIN</td><td>目标注意力序列模型</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/din.html">DIN 教程</a></td></tr><tr><td>DIEN</td><td>兴趣演化序列模型</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/dien.html">DIEN 教程</a></td></tr><tr><td>BST</td><td>Transformer 序列模型</td><td><a href="/torch-rechub/zh/tutorials/models/ranking/bst.html">BST 教程</a></td></tr></tbody></table><h3 id="召回模型" tabindex="-1">召回模型 <a class="header-anchor" href="#召回模型" aria-label="Permalink to “召回模型”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td>DSSM</td><td>双塔语义匹配模型</td><td><a href="/torch-rechub/zh/tutorials/models/matching/dssm.html">DSSM 教程</a></td></tr><tr><td>YoutubeDNN</td><td>YouTube 深度召回模型</td><td><a href="/torch-rechub/zh/tutorials/models/matching/youtube_dnn.html">YoutubeDNN 教程</a></td></tr><tr><td>MIND</td><td>多兴趣胶囊网络召回</td><td><a href="/torch-rechub/zh/tutorials/models/matching/mind.html">MIND 教程</a></td></tr></tbody></table><h3 id="多任务模型" tabindex="-1">多任务模型 <a class="header-anchor" href="#多任务模型" aria-label="Permalink to “多任务模型”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td>MMOE</td><td>多门控专家混合模型</td><td><a href="/torch-rechub/zh/tutorials/models/multi_task/mmoe.html">MMOE 教程</a></td></tr><tr><td>PLE</td><td>渐进分层提取多任务模型</td><td><a href="/torch-rechub/zh/tutorials/models/multi_task/ple.html">PLE 教程</a></td></tr></tbody></table>',12)])])}const b=r(d,[["render",o]]);export{u as __pageData,b as default};
